const __pageData = JSON.parse('{"title":"Justin Deschamps","description":"","frontmatter":{"title":"Justin Deschamps","created":"2026-08-06T00:00:00.000Z","updated":"2026-08-06T00:00:00.000Z","type":"entity","tags":["badlands-media","contributor","fifth-generation-warfare","epistemology"],"sources":["raw/ai-can-help-us-expose-the-nwo.md","raw/badlands-media-show-schedule-78b.md","raw/badlands-media-show-schedule-e18.md","raw/badlands-news-blast.md","raw/badlands-news-brief-024.md","raw/badlands-news-brief-023.md","raw/badlands-news-brief-01d.md","raw/badlands-news-brief-070.md","raw/badlands-news-brief-08c.md","raw/badlands-news-brief-096.md","raw/badlands-news-brief-082.md","raw/badlands-news-brief-0e0.md","raw/badlands-news-brief-138.md","raw/badlands-news-brief-12a.md","raw/badlands-news-brief-1e0.md","raw/badlands-news-brief-1d7.md","raw/badlands-news-brief-3ae.md","raw/badlands-news-brief-423.md","raw/badlands-news-brief-46e.md","raw/badlands-news-brief-550.md","raw/badlands-news-brief-5ec.md","raw/badlands-news-brief-6b6.md","raw/badlands-news-brief-6e3.md","raw/badlands-news-brief-644.md","raw/badlands-news-brief-7ad.md","raw/badlands-news-brief-7a7.md","raw/badlands-news-brief-82f.md","raw/badlands-news-brief-8c5.md"],"confidence":"medium"},"headers":[],"relativePath":"entities/justin-deschamps.md","filePath":"entities/justin-deschamps.md","lastUpdated":null}');
